pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up specific scenario: call play() with 10 wei from a user
        address user = address(0x1234);
        uint amount = 10;
        vm.deal(user, amount);
        vm.prank(user);
        c.play{value: amount}();
        // Assert that after play(), the user's balance is 9 wei (bank got 1) in reference
        // Because random%2 can be 0 or 1, but we need concrete divergence:
        // The mutant only pays out when random==1 (50% chance). To force divergence,
        // we use vm.roll/vm.warp to control block.timestamp and block.difficulty so that random==0.
        vm.warp(12345);
        vm.roll(67890);
        // The above sets block.timestamp=12345, block.difficulty=67890 => keccak256(...)%2 = 0
        // Now call play again with a fresh user
        address user2 = address(0x5678);
        vm.deal(user2, amount);
        vm.prank(user2);
        c.play{value: amount}();
        // In reference, user2 gets pot - 1 = 9 wei; in mutant, user2 gets nothing (pot stays)
        // Check user2's balance: reference has 9, mutant has 0 (since pot wasn't distributed)
        assertTrue(user2.balance == 9);
    }
}

