        // First call: user1 sends 10 wei, pot becomes 10
        vm.prank(user1);
        c.play{value: 10 wei}();

        // Second call: user2 sends 10 wei, pot becomes 20
        // In reference (random==0): user2 gets (20-1)=19 wei, bank gets 1 wei, pot=0
