pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First user: call play() with 10 wei
        address user1 = address(0x1);
        address user2 = address(0x2);
        vm.deal(user1, 10 ether);
        vm.deal(user2, 10 ether);
        vm.prank(user1);
        c.play{value: 10}();

        // Set block.timestamp to a value that makes random == 0 for the reference
        // We need to pick a specific timestamp and difficulty so that (keccak(block.timestamp, block.difficulty) % 2) == 0
        // Let's use block.timestamp = 1, block.difficulty = 1; keccak256(abi.encodePacked(1, 1)) % 2 = 0
        vm.warp(1);

        // Second user: call play() with 10 wei; now the pot is 20
        vm.prank(user2);
        c.play{value: 10}();

        // After the second play, if random == 0 (reference), bank gets 1 wei and user2 gets 19 wei
        // If random == 1 (mutant), nothing is distributed
        // We assert that bank's balance is > 0 (reference passes, mutant fails)
        assertTrue(address(c.bank()).balance > 0);
